  private void handleFailure(Exchange ex, int attemptNo, Throwable cause, List<String> secrets) {
    String op = ex.request.operation();
    ZipkinException error;
    boolean preSend = false;
    boolean retryable = true;
    if (ex.attemptTimedOut || cause instanceof HttpTimeoutException) {
      preSend = cause instanceof HttpConnectTimeoutException;
      String what = preSend ? "connect timed out" : "request timed out";
      error = new TimeoutException(op + ": " + what, null, null, null, sanitize(cause, secrets));
    } else if (cause instanceof CancellationException) {
      error = new CancelledException(op + ": cancelled", cause);
      retryable = false;
    } else if (cause instanceof SSLException) {
      error =
          new UnavailableException(
              op + ": TLS handshake failed (" + cause.getClass().getSimpleName() + ")",
              null,
              null,
              null,
              sanitize(cause, secrets));
      retryable = false;
    } else {
      preSend = isConnectFailure(cause);
      String what = preSend ? "connection failed" : "network error";
      error =
          new UnavailableException(
              op + ": " + what + " (" + rootName(cause) + ")",
              null,
              null,
              null,
              sanitize(cause, secrets));
    }
    boolean allowed = retryable && (ex.request.idempotent() || preSend);
    if (!allowed || attemptNo > ex.maxRetries) {
      notifyError(ex, attemptNo, error, false);
      fail(ex, error);
      return;
    }
    scheduleRetry(ex, attemptNo, error, config.retry().backoff(attemptNo - 1));
  }

  private void scheduleRetry(Exchange ex, int n, ZipkinException error, Duration wait) {
    if (wait.toNanos() >= ex.remainingNanos()) {
      notifyError(ex, n, error, false);
      fail(ex, timeoutTotal(ex, error));
      return;
    }
    notifyError(ex, n, error, true);
    Map<String, Object> fields = new LinkedHashMap<>();
    fields.put("method", ex.request.method());
    fields.put("url", ex.redactedUrl);
    fields.put("attempt", n);
    fields.put("code", error.code().wireValue());
    fields.put("waitMs", wait.toMillis());
    safeLog("debug", "retrying request", fields);
    CompletableFuture.delayedExecutor(wait.toNanos(), TimeUnit.NANOSECONDS)
        .execute(() -> attempt(ex));
  }

